cd /home/admin/backend && php artisan tinker --execute="
\$student = DB::table('Student')->where('name', '陳顥昀')->first();
if (\$student) {
    echo 'Student: id=' . \$student->id . ', name=' . \$student->name . ', CampusID=' . \$student->CampusID . PHP_EOL;
    \$courses = DB::table('StudentClass')->where('StudentID', \$student->id)->get();
    foreach (\$courses as \$c) {
        echo 'Course ID=' . \$c->ID . ', SubjectID=' . \$c->SubjectID . ', SessionCount=' . \$c->SessionCount . ', RemainingSessions=' . \$c->RemainingSessions . ', UsedSessions=' . \$c->UsedSessions . ', Stop=' . \$c->Stop . PHP_EOL;
        \$sessions = DB::table('ClassSession')->where('StudentClassID', \$c->ID)->get();
        \$statusCounts = \$sessions->groupBy('Status')->map->count();
        echo '  ClassSessions status counts: ' . json_encode(\$statusCounts) . PHP_EOL;
    }
} else {
    echo 'Student not found';
}
" 2>/dev/null

cd /home/admin/backend && php artisan tinker --execute="
