cd /home/admin/backend && php artisan tinker --execute="
use Illuminate\Support\Facades\DB;
\$courses = DB::table('StudentClass')->where('StudentID', 77)->get();
foreach (\$courses as \$c) {
    \$subj = DB::table('Subject')->where('id', \$c->SubjectID)->first();
    echo '=== Course ID=' . \$c->ID . ' ===' . PHP_EOL;
    echo '  Subject: ' . (\$subj ? \$subj->Subject_Name : 'N/A') . ' (id=' . \$c->SubjectID . ')' . PHP_EOL;
    echo '  ClassType: ' . \$c->ClassType . PHP_EOL;
    echo '  SessionCount: ' . \$c->SessionCount . ', monthly_sessions: ' . \$c->monthly_sessions . PHP_EOL;
    echo '  RemainingSessions: ' . \$c->RemainingSessions . ', UsedSessions: ' . \$c->UsedSessions . PHP_EOL;
    echo '  ScheduleMode: ' . \$c->ScheduleMode . PHP_EOL;
    echo '  week1: ' . \$c->week1 . ', week2: ' . \$c->week2 . PHP_EOL;
    echo '  time1: ' . \$c->time1 . ', time2: ' . \$c->time2 . PHP_EOL;
    echo '  StartDate: ' . \$c->StartDate . ', EndDate: ' . \$c->EndDate . PHP_EOL;
    echo '  Stop: ' . \$c->Stop . PHP_EOL;
    echo PHP_EOL;
}
" 2>/dev/null

